def import_records(store: Store, rows: list[dict]) -> int:
    seen = set(store.record_ids)
    pending = []
    for row in rows:
        record_id = row.get("record_id")
        if not record_id or "value" not in row:
            raise ValueError("each row requires record_id and value")
        if record_id not in seen:
            seen.add(record_id)
            pending.append(row)
    store.bulk_insert(pending)
    return len(pending)
